using System.Text.Json;
using SysAdminAssistant.Core;
namespace SysAdminAssistant.Infrastructure;
public sealed class AgentEventProblem {public string Id {get;set;}=Guid.NewGuid().ToString("N");public string RuleId {get;set;}="";public string Source {get;set;}="";public string Title {get;set;}="";public Severity Severity {get;set;}public DateTime LastUtc {get;set;}public int Count {get;set;}public bool Open {get;set;}=true;public bool Notified {get;set;}public Severity NotifiedSeverity {get;set;}public int QuietMinutes {get;set;}public DateTime? ClosedUtc {get;set;}public string Resolution {get;set;}="";public DateTime? FirstUtc {get;set;}public DateTime? LastEventUtc {get;set;}public string Signature {get;set;}="";}
public sealed class AgentEventState {public DateTime LastLoginSampleUtc {get;set;} public bool ArchiveSeeded {get;set;}public Dictionary<string,string> ProblemArchiveDigests {get;set;}=[];public AgentEventPolicy Policy {get;set;}=new();public List<AgentJournalEvent> Events {get;set;}=[];public List<AgentEventProblem> Problems {get;set;}=[];public List<string> Seen {get;set;}=[];public AgentJournalHealth[] Health {get;set;}=[];public List<NetworkNotification> Pending {get;set;}=[];public string UpdateFingerprint {get;set;}="";public DateTime? RecoveryHealthySince {get;set;}public DateTime? RecoveryBootUtc {get;set;}public DateTime? RecoveryLastReportUtc {get;set;}}
public sealed record AgentJournalHistoryPage(AgentJournalEvent[] Events,DateTime? BeforeUtc,string? BeforeKey);
public sealed class AgentEventStore(string directory,bool linux=false)
{
 private T With<T>(int id,Func<AgentEventState,T> action,bool write=false){if(id<1)throw new ArgumentException();var path=Path.Combine(directory,(linux?"agent-linux-events-":"agent-events-")+id+".json");return NetworkStore.Locked(path,()=>{var s=File.Exists(path)?JsonSerializer.Deserialize<AgentEventState>(File.ReadAllText(path),AgentWire.Json)??throw new InvalidDataException():linux?new AgentEventState{Policy=new AgentEventPolicy{Rules=AgentEvents.StandardLinux()}}:new();var result=action(s);if(write){ArchiveProblems(id,s);var tmp=path+".tmp";using(var f=new FileStream(tmp,FileMode.Create,FileAccess.Write,FileShare.None,4096,FileOptions.WriteThrough)){JsonSerializer.Serialize(f,s,AgentWire.Json);f.Flush(true);}File.Move(tmp,path,true);}return result;});}
 private static string EventSignature(string rule,AgentJournalEvent e){if(rule=="fail-login")return "device-login-failures";if(rule is "reboot" or "fail-login" or "linux-login" or "logon-success")return AgentWire.Hash(rule+"|"+e.Source);var code=System.Text.RegularExpressions.Regex.Match(e.Message,@"0x[0-9a-fA-F]{4,16}|Failed with result .[^.]{1,40}",System.Text.RegularExpressions.RegexOptions.CultureInvariant,TimeSpan.FromMilliseconds(50)).Value;return AgentWire.Hash(rule+"|"+e.Provider+"|"+e.Id+"|"+e.Source+"|"+code);}
 private void AppendOccurrence(int id,AgentJournalEvent e){var folder=Path.Combine(directory,linux?"linux-event-history":"windows-event-history");Directory.CreateDirectory(folder);var path=Path.Combine(folder,id+"-"+DateTime.UtcNow.ToString("yyyyMMdd")+".ndjson");using var file=new FileStream(path,FileMode.Append,FileAccess.Write,FileShare.Read,4096,FileOptions.WriteThrough);var bytes=System.Text.Encoding.UTF8.GetBytes(JsonSerializer.Serialize(e,AgentWire.Json)+"\n");file.Write(bytes);file.Flush(true);}
 private void ArchiveProblems(int id,AgentEventState state)
 {
    var folder=Path.Combine(directory,linux?"linux-problem-history":"windows-problem-history");Directory.CreateDirectory(folder);var path=Path.Combine(folder,id+"-"+DateTime.UtcNow.ToString("yyyyMMdd")+".ndjson");
    foreach(var problem in state.Problems){var json=JsonSerializer.Serialize(problem,AgentWire.Json);var digest=AgentWire.Hash(json);if(state.ProblemArchiveDigests.GetValueOrDefault(problem.Id)==digest)continue;using(var file=new FileStream(path,FileMode.Append,FileAccess.Write,FileShare.Read,4096,FileOptions.WriteThrough)){var bytes=System.Text.Encoding.UTF8.GetBytes(json+"\n");file.Write(bytes);file.Flush(true);}state.ProblemArchiveDigests[problem.Id]=digest;}
    var retained=state.Problems.Select(p=>p.Id).ToHashSet();foreach(var key in state.ProblemArchiveDigests.Keys.Where(k=>!retained.Contains(k)).ToArray())state.ProblemArchiveDigests.Remove(key);
 }
 private static void Close(AgentEventProblem p,DateTime now,string reason){p.Open=false;p.ClosedUtc=now;p.Resolution=reason;}
 public AgentJournalHistoryPage History(int id,DateTime? before,string? beforeKey,CancellationToken token)
 {
    var folder=Path.Combine(directory,linux?"linux-event-history":"windows-event-history");if(!Directory.Exists(folder))return new([],null,null);
    var rows=new SortedDictionary<(DateTime,string),AgentJournalEvent>();int read=0;
    foreach(var path in Directory.EnumerateFiles(folder,id+"-*.ndjson").OrderByDescending(x=>x))foreach(var line in File.ReadLines(path)){
        if(++read%128==0)token.ThrowIfCancellationRequested();if(line.Length>20000)continue;AgentJournalEvent? e;try{e=JsonSerializer.Deserialize<AgentJournalEvent>(line,AgentWire.Json);}catch(JsonException){continue;}if(e==null)continue;
        if(before!=null&&(e.TimeUtc>before||e.TimeUtc==before&&string.CompareOrdinal(e.Key,beforeKey)>=0))continue;
        rows[(e.TimeUtc,e.Key)]=e;if(rows.Count>200)rows.Remove(rows.Keys.First());
    }
    var result=rows.Values.Reverse().ToArray();return new(result,result.Length==200?result.Last().TimeUtc:null,result.Length==200?result.Last().Key:null);
 }
 public AgentEventState View(int id)=>With(id,s=>s);
 public AgentEventPolicy Save(AgentEventsSave request){AgentEvents.Validate(request.Policy);return With(request.DeviceId,s=>{if(s.Policy.Version!=request.ExpectedVersion)throw new InvalidOperationException(global::SysAdminAssistant.Core.ProductText.Get("Правила изменились; обновите окно"));request.Policy.Version=s.Policy.Version+1;s.Policy=request.Policy;return s.Policy;},true);}
 public void Resolve(int id,string key)=>With(id,s=>{var p=s.Problems.Single(p=>p.Id==key);Close(p,DateTime.UtcNow,"Отмечено решённым пользователем");s.Pending.RemoveAll(n=>n.EntityKey=="journal:"+id+":"+p.Id);return true;},true);
 public void Ingest(int id,AgentEventBatch? batch,OsUpdateStatus? updates,bool maintenance,DateTime now)=>With(id,s=>{
 if(!s.ArchiveSeeded){foreach(var prior in s.Events)AppendOccurrence(id,prior);s.ArchiveSeeded=true;}
 if(batch!=null){AgentEvents.Validate(batch);s.Health=batch.Health;

 var signatureCache=new Dictionary<string,string>();string Signature(string id,AgentJournalEvent row){var key=id+"|"+row.Key;if(!signatureCache.TryGetValue(key,out var value))signatureCache[key]=value=EventSignature(id,row);return value;}
 if(s.Policy.Enabled)foreach(var e in batch.Events.OrderBy(e=>e.TimeUtc)){
 if(s.Seen.Contains(e.Key))continue;s.Seen.Add(e.Key);s.Events.Add(e);if(e.Id!=4625||e.Channel!="Security"||e.TimeUtc>=s.LastLoginSampleUtc.AddMinutes(1)){AppendOccurrence(id,e);if(e.Id==4625&&e.Channel=="Security")s.LastLoginSampleUtc=e.TimeUtc;}
 if(linux&&(e.TimeUtc<now.AddHours(-1)||AgentEvents.IgnoredFloppy(e)))continue;
 foreach(var rule in s.Policy.Rules.Where(r=>r.Enabled&&r.Channel==e.Channel&&r.Provider.Equals(e.Provider,StringComparison.OrdinalIgnoreCase)&&r.Ids.Contains(e.Id)&&(r.Contains==""||e.Message.Contains(r.Contains,StringComparison.OrdinalIgnoreCase)))){
 if(rule.Id is "ntfs" or "ntfs2"&&rule.Contains==""&&AgentEvents.HealthyNtfs(e))continue;
 if(rule.Id=="defender-on")foreach(var p in s.Problems.Where(p=>p.RuleId=="defender-off"))p.Open=false;
 if(rule.Severity==Severity.Info)continue;
 var reboot=rule.Id is "power" or "shutdown" or "bsod";var ruleId=reboot?"reboot":rule.Id;var source=reboot||ruleId=="fail-login"?"":e.Source;
 if(rule.Id=="logon-success"&&!s.Problems.Any(p=>p.Open&&p.RuleId=="fail-login"&&now-p.LastUtc<=TimeSpan.FromMinutes(10)&&source.Length>0&&s.Events.Any(x=>x.Channel=="Security"&&x.Provider==e.Provider&&x.Id==4625&&x.Source==source&&x.TimeUtc<=e.TimeUtc&&x.TimeUtc>=e.TimeUtc.AddMinutes(-10))))continue;
 var signature=Signature(ruleId,e);
 var matchingEvents=s.Events.Where(x=>!AgentEvents.IgnoredFloppy(x)&&x.Channel==rule.Channel&&x.Provider.Equals(rule.Provider,StringComparison.OrdinalIgnoreCase)&&rule.Ids.Contains(x.Id)&&(ruleId=="fail-login"||x.Source==source)&&Signature(ruleId,x)==signature&&(rule.Contains==""||x.Message.Contains(rule.Contains,StringComparison.OrdinalIgnoreCase))&&!((rule.Id is "ntfs" or "ntfs2")&&rule.Contains==""&&AgentEvents.HealthyNtfs(x))&&x.TimeUtc<=e.TimeUtc&&x.TimeUtc>=e.TimeUtc.AddMinutes(-rule.WindowMinutes)).ToArray();var count=matchingEvents.Length;
 var existing=s.Problems.FirstOrDefault(p=>p.Open&&p.RuleId==ruleId&&p.Source==source&&(p.Signature==""||p.Signature==signature));
 if(existing!=null){existing.Signature=signature;existing.LastEventUtc=e.TimeUtc;existing.Count++;existing.LastUtc=now;if(rule.CriticalThreshold>0&&count>=rule.CriticalThreshold)existing.Severity=Severity.Critical;continue;}

 if(count<rule.Threshold)continue;
 if(s.Problems.Count(p=>p.Open)>=1000)throw new IOException(global::SysAdminAssistant.Core.ProductText.Get("Слишком много открытых событий; требуется разбор"));
 s.Problems.Add(new(){FirstUtc=matchingEvents.Min(x=>x.TimeUtc),LastEventUtc=e.TimeUtc,Signature=signature,RuleId=ruleId,Source=source,Title=(reboot?"Аварийная перезагрузка / сбой Windows":rule.Name)+(source==""?"":" · "+source),Severity=rule.CriticalThreshold>0&&count>=rule.CriticalThreshold?Severity.Critical:rule.Severity,Count=count,LastUtc=now,QuietMinutes=rule.QuietMinutes});
 }
 }
 if(linux)foreach(var p in s.Problems.Where(p=>p.Open&&p.RuleId=="linux-storage")){
 var related=s.Events.Where(e=>e.Channel=="Linux"&&e.Provider.Equals("journald",StringComparison.OrdinalIgnoreCase)&&e.Id==1002&&e.Source==p.Source&&e.TimeUtc>=(p.FirstUtc??p.LastUtc)&&e.TimeUtc<=(p.LastEventUtc??p.LastUtc)).ToArray();
 if(related.Length>=p.Count&&related.All(AgentEvents.IgnoredFloppy)){Close(p,now,"Пересмотр классификации: ошибки неиспользуемого floppy fdN исключены; исходный журнал сохранён.");s.Pending.RemoveAll(n=>n.EntityKey=="journal:"+id+":"+p.Id);}}
 foreach(var p in s.Problems.Where(p=>p.Open&&(p.RuleId is "ntfs" or "ntfs2"))){if(s.Seen.Count>s.Events.Count)continue;var rule=s.Policy.Rules.FirstOrDefault(r=>r.Id==p.RuleId);if(rule==null||rule.Contains!="")continue;var related=s.Events.Where(e=>e.Channel==rule.Channel&&e.Provider.Equals(rule.Provider,StringComparison.OrdinalIgnoreCase)&&rule.Ids.Contains(e.Id)&&e.Source==p.Source).ToArray();if(related.Length>0&&related.All(AgentEvents.HealthyNtfs))Close(p,now,"Пересмотр классификации: сохранены только информационные NTFS 98 об исправном томе; история сохранена.");}
 foreach(var p in s.Problems.Where(p=>p.Open&&p.QuietMinutes>0)){var rule=s.Policy.Rules.FirstOrDefault(r=>r.Id==p.RuleId);if(rule!=null&&s.Health.Any(h=>h.Channel==rule.Channel&&h.State=="OK")){if(now-p.LastUtc>=TimeSpan.FromMinutes(p.QuietMinutes))Close(p,now,"Завершился период тишины при доступном журнале");}else p.LastUtc=now;}
 s.Events=s.Events.TakeLast(2000).ToList();s.Seen=s.Seen.TakeLast(8000).ToList();s.Problems=s.Problems.Where(p=>p.Open).Concat(s.Problems.Where(p=>!p.Open).TakeLast(1000)).ToList();
 }
 if(!maintenance)foreach(var p in s.Problems.Where(p=>p.Open&&(!p.Notified||p.Severity>p.NotifiedSeverity))){if(s.Policy.Rules.Any(r=>(r.Id==p.RuleId||p.RuleId=="reboot"&&(r.Id is "power" or "shutdown" or "bsod"))&&r.Notify)){if(s.Pending.Count>=8000)throw new IOException(global::SysAdminAssistant.Core.ProductText.Get("Очередь уведомлений заполнена"));s.Pending.Add(new(){Topic=p.RuleId is "reboot"?"journal.reboot":p.RuleId.Contains("logon")||p.RuleId.Contains("login")||p.RuleId.Contains("security")?"journal.security":p.RuleId.Contains("ntfs")||p.RuleId.Contains("disk")?"journal.storage":"journal.other",EntityKey="journal:"+id+":"+p.Id,Source=(linux?"Журналы Linux · устройство ":"Журналы Windows · устройство ")+id,Title=p.Title+"\n"+AgentEventExplanation.Describe(s,p,false),Severity=p.Severity,CreatedAt=now});}p.Notified=true;p.NotifiedSeverity=p.Severity;}
 s.Pending.RemoveAll(n=>UpdateNotifications.IsAvailability(n.EntityKey));
 return true;},true);
 public void Recover(int id,AgentReport report,AgentPolicy policy,DateTime now,DateTime[]? observedReboots=null)=>With(id,s=>{
 var fresh=report.CapturedUtc.Kind==DateTimeKind.Utc&&report.CapturedUtc<=now.AddSeconds(30)&&now-report.CapturedUtc<=TimeSpan.FromSeconds(Math.Max(90,policy.IntervalSeconds*3));
 var boot=report.CapturedUtc.AddSeconds(-report.UptimeSeconds);var repeated=(observedReboots??[]).Count(t=>t>=now.AddMinutes(-30)&&t<=now)>=3||s.Events.Where(e=>e.Channel=="System"&&(e.Id==41&&e.Provider=="Microsoft-Windows-Kernel-Power"||e.Id==6008&&e.Provider=="EventLog"||e.Id==1001&&e.Provider=="Microsoft-Windows-WER-SystemErrorReporting")&&e.TimeUtc>=now.AddMinutes(-30)&&e.TimeUtc<=now).GroupBy(e=>(e.Provider,e.Id)).Any(g=>g.Count()>=3);
 var telemetryHealthy=!AgentChecks.Evaluate(report,policy).Any(f=>f.Severity is Severity.Warning or Severity.Critical);
 var systemReadable=report.EventBatch?.Health.Any(h=>h.Channel=="System"&&h.State=="OK")==true;
 if(!fresh||!telemetryHealthy||!systemReadable||repeated||s.RecoveryLastReportUtc!=null&&report.CapturedUtc<=s.RecoveryLastReportUtc){if(!fresh||!telemetryHealthy||!systemReadable||repeated)s.RecoveryHealthySince=null;return false;}
 if(s.RecoveryBootUtc==null||Math.Abs((boot-s.RecoveryBootUtc.Value).TotalSeconds)>60||s.RecoveryLastReportUtc==null||report.CapturedUtc-s.RecoveryLastReportUtc>TimeSpan.FromSeconds(Math.Max(90,policy.IntervalSeconds*3)))s.RecoveryHealthySince=report.CapturedUtc;
 s.RecoveryHealthySince??=report.CapturedUtc;s.RecoveryBootUtc=boot;s.RecoveryLastReportUtc=report.CapturedUtc;
 if(report.UptimeSeconds>=Math.Max(120,policy.BootGraceMinutes*60)&&report.CapturedUtc-s.RecoveryHealthySince>=TimeSpan.FromMinutes(2))foreach(var p in s.Problems.Where(p=>p.Open&&p.RuleId=="reboot")){Close(p,now,"Свежие данные агента: система работает стабильно, показатели и контролируемые службы в норме. Причина перезагрузки автоматически не устанавливается.");s.Pending.RemoveAll(n=>n.EntityKey=="journal:"+id+":"+p.Id);}
 return true;},true);
 public void RecoverLinux(int id,AgentReport report,AgentPolicy policy,DateTime now)=>With(id,s=>{if(report.Errors.Contains("Не удалось получить службы systemd",StringComparer.Ordinal)||report.CapturedUtc.Kind!=DateTimeKind.Utc||report.CapturedUtc>now.AddSeconds(30)||now-report.CapturedUtc>TimeSpan.FromSeconds(Math.Max(90,policy.IntervalSeconds*3)))return false;foreach(var p in s.Problems.Where(p=>p.Open&&p.RuleId=="linux-service")){var unit=report.Linux?.Units.FirstOrDefault(u=>u.Name==p.Source);var successfulUnit=unit!=null&&unit.Error==""&&(unit.Type=="oneshot"?LinuxPolicy.SuccessfulCompletion(unit,p.LastEventUtc??p.FirstUtc??p.LastUtc,report.CapturedUtc):unit.Active=="active"||LinuxPolicy.SocketActivated(unit,report));if(successfulUnit||report.Linux==null&&unit==null&&report.Services.Any(service=>service.Name.Equals(p.Source,StringComparison.OrdinalIgnoreCase)&&service.Status=="Running")){Close(p,now,"Служба снова работает");s.Pending.RemoveAll(n=>n.EntityKey=="journal:"+id+":"+p.Id);}}return true;},true);
 public void Flush(int id,NetworkStore network)=>With(id,s=>{s.Pending.RemoveAll(n=>UpdateNotifications.IsAvailability(n.EntityKey));network.State(n=>{UpdateNotifications.Suppress(n);var closed=s.Problems.Where(p=>!p.Open).Select(p=>"journal:"+id+":"+p.Id).ToHashSet();foreach(var item in n.Notifications.Where(x=>x.HandledAt==null&&closed.Contains(x.EntityKey))){item.HandledAt=DateTime.UtcNow;item.Result="Состояние восстановлено / событие закрыто";}foreach(var p in s.Problems.Where(p=>!p.Open)){var key="journal:"+id+":"+p.Id;var sent=n.Notifications.FirstOrDefault(x=>x.EntityKey==key&&x.Result=="Отправлено");if(sent!=null&&!n.Notifications.Any(x=>x.EntityKey==key+":recovery"))n.Notifications.Add(new(){EntityKey=key+":recovery",Topic=sent.Topic,Source=sent.Source,Title=p.Title+" · "+p.Resolution,Severity=p.Severity,Transition="ЗАКРЫТО / ВОССТАНОВЛЕНО"});}foreach(var item in s.Pending)if(!n.Notifications.Any(x=>x.Id==item.Id))n.Notifications.Add(item);return true;},true);s.Pending.Clear();return true;},true);
 public AgentFinding[] Findings(int id)=>With(id,s=>{if(!s.Policy.Enabled)return Array.Empty<AgentFinding>();return (s.Health.Length==0&&s.Policy.Rules.Any(r=>r.Enabled)?new[]{new AgentFinding("journal-reader:pending",linux?"Ожидание журналов Linux":"Ожидание журналов Windows; обновите агент до 0.12.0",Severity.Warning,2)}:Array.Empty<AgentFinding>()).Concat(s.Problems.Where(p=>p.Open).Select(p=>new AgentFinding("journal:"+p.Id,p.Title+" · событий: "+p.Count,p.Severity,0))).Concat(s.Health.Where(h=>h.State is not("OK" or "Absent")).Select(h=>new AgentFinding("journal-reader:"+h.Channel,h.Channel+": "+h.Detail,Severity.Warning,2))).ToArray();});
}
